// ── item builders ────────────────────────────────────────────────────────────
function _item(d){
  if(!d||d.id===undefined||d.id===null||!d.title)return null;
  return { id:'kisskh-'+d.id, title:String(d.title), url:'kisskh://drama/'+d.id,
           type:'anime', cover:d.thumbnail?String(d.thumbnail):null };
}
function _items(arr){
  var out=[],i,it;
  for(i=0;i<(arr||[]).length;i++){it=_item(arr[i]);if(it)out.push(it);}
  return out;
}
function _epNum(n){
  if(typeof n==='number'&&isFinite(n))return n;
  var p=parseFloat(n);
  return isFinite(p)?p:0;
}

function getHome(opts) {
  var rows=[
    { title:'Trending Now', path:'/api/DramaList/MostView' },
    { title:'Latest Updates', path:'/api/DramaList/LastUpdate' },
    { title:'Top Rated', path:'/api/DramaList/TopRating' }
  ];
  var jobs=rows.map(function(r){
    return _api(r.path,'home '+r.title).then(function(j){return{title:r.title,items:_items(j)};},
      function(){return{title:r.title,items:[]};});
  });
  return Promise.all(jobs).then(function(rs){
    var out=[],i;
    for(i=0;i<rs.length;i++)if(rs[i].items.length)out.push(rs[i]);
    if(!out.length)return _fail('home empty');
    return out;
  });
}

function search(query, page, opts) {
  var q=String(query||'').trim();
  if(!q)return _fail('empty query');
  return _api('/api/DramaList/Search?q='+encodeURIComponent(q),'search').then(function(j){
    var items=_items(j);
    if(!items.length)return _fail('no results');
    return items;
  });
}

function _detail(id){
  return _api('/api/DramaList/Drama/'+encodeURIComponent(id)+'?isq=false','detail '+id);
}

function getDetail(url, opts) {
  var id=String(url||'').replace('kisskh://drama/','');
  if(!id)return _fail('bad detail url');
  return _detail(id).then(function(d){
    if(!d||!d.title)return _fail('detail empty');
    var eps=_epsFromDetail(d);
    var year=null;
    if(d.releaseDate!==undefined&&d.releaseDate!==null&&String(d.releaseDate)!=='')
      year=String(d.releaseDate).slice(0,4);
    return { id:'kisskh-'+d.id, title:String(d.title), url:'kisskh://drama/'+d.id,
             type:'anime', cover:d.thumbnail?String(d.thumbnail):null,
             description:d.description?String(d.description):null,
             year:year, episodes:eps };
  });
}

function _epsFromDetail(d){
  var eps=d.episodes||[],out=[],i;
  for(i=0;i<eps.length;i++){
    var e=eps[i],n=_epNum(e.number);
    out.push({ id:'kisskh://ep/'+e.id, title:'Episode '+n, url:'kisskh://ep/'+e.id,
               number:n, thumbnail:d.thumbnail?String(d.thumbnail):null });
  }
  out.sort(function(a,b){return a.number-b.number;});
  return out;
}

function getEpisodes(url, opts) {
  var id=String(url||'').replace('kisskh://drama/','');
  if(!id)return _fail('bad episodes url');
  return _detail(id).then(function(d){
    var eps=_epsFromDetail(d);
    if(!eps.length)return _fail('no episodes');
    return eps;
  });
}

// ── video sources ────────────────────────────────────────────────────────────
function _resolveVideoField(v){
  // Returns array of {url, quality?} from the `Video` field shapes.
  if(!v)return[];
  if(typeof v==='string'){
    var s=v.trim();
    if(!s)return[];
    if(s.indexOf('http')===0){
      if(s.indexOf('tickcounter.com')>=0)return[]; // not released yet
      return[{url:s}];
    }
    var dec=_decryptVideo(s);
    if(dec)return[{url:dec}];
    return[];
  }
  if(typeof v==='object'){
    var out=[],q=v.qualities||{};
    var keys=Object.keys(q),i;
    keys.sort(function(a,b){return parseInt(b,10)-parseInt(a,10);});
    for(i=0;i<keys.length;i++){
      var u=String(q[keys[i]]||'');
      if(u.indexOf('http')===0)out.push({url:u,quality:/^\d+$/.test(keys[i])?keys[i]+'p':String(keys[i])});
    }
    if(!out.length&&v.url&&String(v.url).indexOf('http')===0)out.push({url:String(v.url)});
    return out;
  }
  return[];
}

function _subLang(s){
  var land=s.land||s.lang||'';
  if(land&&/^[a-z]{2,3}$/i.test(land))return land.toLowerCase();
  var label=String(s.label||'');
  var m=/\((en|id|ms|ar|km|th|vi|es|pt|fr|de)\)/i.exec(label);
  if(m)return m[1].toLowerCase();
  return label?label.toLowerCase().replace(/[^a-z]/g,'')||'sub':'sub';
}

function getVideoSources(episodeUrl) {
  var epId=String(episodeUrl||'').replace('kisskh://ep/','');
  if(!epId)return _fail('bad episode url');
  var token;
  try{token=_kkey(epId,KISS_VI_GUID);}catch(e){return _fail('token failed: '+e.message);}
  return _api('/api/DramaList/Episode/'+encodeURIComponent(epId)+'.png?err=false&ts=&time=&kkey='+token,'episode '+epId)
  .then(function(j){
    var vids=_resolveVideoField(j&&j.Video);
    if(!vids.length)return _fail('no stream link (episode may not be released yet)');
    var subToken;
    try{subToken=_kkey(epId,KISS_SUB_GUID);}catch(e){subToken=null;}
    var subP=subToken?_api('/api/Sub/'+encodeURIComponent(epId)+'?kkey='+subToken,'subs '+epId).then(
      function(s){return s;},function(){return[];}):Promise.resolve([]);
    return subP.then(function(subs){
      var subList=[],i;
      for(i=0;i<(subs||[]).length;i++){
        var s=subs[i],src=String(s.src||'');
        // Only direct subtitle files; encrypted .txt subs can't be served raw.
        if(/^https?:\/\//i.test(src)&&/\.(srt|vtt)(\?|$)/i.test(src))
          subList.push({url:src,lang:_subLang(s),label:String(s.label||_subLang(s))});
      }
      var out=[];
      for(i=0;i<vids.length;i++){
        var e={url:vids[i].url,label:'KissKH'+(vids[i].quality?' ['+vids[i].quality+']':''),
               container:/\.m3u8(\?|$)/i.test(vids[i].url)?'hls':'mp4',
               headers:{'Referer':KISS_BASE+'/','User-Agent':KISS_UA}};
        if(vids[i].quality)e.quality=vids[i].quality;
        if(subList.length)e.subtitles=subList;
        out.push(e);
      }
      return out;
    });
  });
}
